import{_ as a,o as l,c as i,ak as s}from"./chunks/framework.D8TdBi6N.js";const m=JSON.parse('{"title":"编译阶段","description":"","frontmatter":{},"headers":[],"relativePath":"zh/reference/compilation-phases.md","filePath":"zh/reference/compilation-phases.md","lastUpdated":1782452117000}'),o={name:"zh/reference/compilation-phases.md"};function t(r,e,c,d,n,h){return l(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="编译阶段" tabindex="-1">编译阶段 <a class="header-anchor" href="#编译阶段" aria-label="Permalink to “编译阶段”">​</a></h1><p>BON 解析器按以下四个阶段处理源文件：</p><h2 id="阶段-1-词法-语法分析" tabindex="-1">阶段 1：词法/语法分析 <a class="header-anchor" href="#阶段-1-词法-语法分析" aria-label="Permalink to “阶段 1：词法/语法分析”">​</a></h2><ul><li>识别并跳过注释</li><li>构建抽象语法树 (AST)</li><li>收集所有顶层模板定义和类定义</li></ul><h2 id="阶段-2-导入解析" tabindex="-1">阶段 2：导入解析 <a class="header-anchor" href="#阶段-2-导入解析" aria-label="Permalink to “阶段 2：导入解析”">​</a></h2><ul><li>递归加载所有 <code>import</code> 文件</li><li>合并命名空间，检测循环依赖</li></ul><h2 id="阶段-3-模板展开" tabindex="-1">阶段 3：模板展开 <a class="header-anchor" href="#阶段-3-模板展开" aria-label="Permalink to “阶段 3：模板展开”">​</a></h2><ul><li>遇到 <code>{template}</code> 或裸模板标识符时，执行深拷贝替换</li><li>模板内部若包含引用，递归展开（最大递归深度 100）</li></ul><h2 id="阶段-4-实例化与常量折叠" tabindex="-1">阶段 4：实例化与常量折叠 <a class="header-anchor" href="#阶段-4-实例化与常量折叠" aria-label="Permalink to “阶段 4：实例化与常量折叠”">​</a></h2><ul><li>遇到 <code>ClassName { ... }</code> 时，合并属性，绑定继承链</li><li>计算属性按依赖顺序求值</li><li><code>.method()</code> 调用立即执行，结果替换为字面量</li><li><code>std.*</code> 函数计算结果直接替换原 AST 节点</li><li><code>$var</code> 参数替换为传递的值</li><li><code>if</code>/<code>else</code> 表达式按条件求值，选择分支替换</li><li><code>for</code>/<code>in</code> 循环遍历数组/对象，生成新的数组</li></ul><h2 id="最终产物" tabindex="-1">最终产物 <a class="header-anchor" href="#最终产物" aria-label="Permalink to “最终产物”">​</a></h2><p>完全展开、所有函数调用均已消除的<strong>纯 JSON 数据结构</strong>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark" style="background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee;" tabindex="0"><code><span class="line"><span>BON 源码 → [词法分析] → [语法分析] → [导入解析] → [模板展开] → [实例化与常量折叠] → 纯 JSON</span></span>
<span class="line"><span></span></span></code></pre></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>BON 是<strong>编译期</strong>语言，所有逻辑在解析时完成。宿主程序拿到的永远是纯 JSON，不需要运行时依赖。</p></div>`,14)])])}const f=a(o,[["render",t]]);export{m as __pageData,f as default};
